        stderr=subprocess.STDOUT,
        check=False,
        text=True,
    )
    require(run.returncode == 0, "VALIDATOR_NONZERO\n" + run.stdout)
    require("VALIDATION=PASS" in run.stdout, "VALIDATOR_MARKER")
    return run.stdout

